+package com.example;
+
+import org.springframework.stereotype.Service;
+
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Deliberately in-memory: messages last for the life of the application, including
+ * navigating away from and back to the contact view.
+ */
+@Service
+public class ContactMessageStore {
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
